Link: https://lore.kernel.org/r/20260123141540.76540-1-tvrtko.ursulin@igalia.com

Here is the root cause:
The drm_gem_change_handle_ioctl() function does not validate that the new_handle parameter (a u32 from userspace) is within the int range required by idr_alloc(). Passing a value > INT_MAX causes a negative start value when cast to int, triggering a kernel warning in idr_alloc().

Here is the patch:

 int drm_gem_change_handle_ioctl(struct drm_device *dev, void *data,
 				struct drm_file *file_priv)
 {
 	struct drm_gem_change_handle *args = data;
 	struct drm_gem_object *obj;
-	int ret;
+	int handle, ret;

 	if (!drm_core_check_feature(dev, DRIVER_GEM))
 		return -EOPNOTSUPP;

+	/* idr_alloc() limitation. */
+	if (args->new_handle > INT_MAX)
+		return -EINVAL;
+	handle = args->new_handle;
+
 	obj = drm_gem_object_lookup(file_priv, args->handle);
 	if (!obj)
 		return -ENOENT;

-	if (args->handle == args->new_handle) {
+	if (args->handle == handle) {
 		ret = 0;
 		goto out;
 	}

 	mutex_lock(&file_priv->prime.lock);

 	spin_lock(&file_priv->table_lock);
-	ret = idr_alloc(&file_priv->object_idr, obj,
-		args->new_handle, args->new_handle + 1, GFP_NOWAIT);
+	ret = idr_alloc(&file_priv->object_idr, obj, handle, handle + 1,
+			GFP_NOWAIT);
 	spin_unlock(&file_priv->table_lock);

 	if (ret < 0)
 		goto out_unlock;

 	if (obj->dma_buf) {
-		ret = drm_prime_add_buf_handle(&file_priv->prime, obj->dma_buf, args->new_handle);
+		ret = drm_prime_add_buf_handle(&file_priv->prime, obj->dma_buf,
+					       handle);
 		if (ret < 0) {
 			spin_lock(&file_priv->table_lock);
-			idr_remove(&file_priv->object_idr, args->new_handle);
+			idr_remove(&file_priv->object_idr, handle);
 			spin_unlock(&file_priv->table_lock);
 			goto out_unlock;
 		}

 		drm_prime_remove_buf_handle(&file_priv->prime, args->handle);
 	}

 	ret = 0;

 	spin_lock(&file_priv->table_lock);
 	idr_remove(&file_priv->object_idr, args->handle);
 	spin_unlock(&file_priv->table_lock);

 out_unlock:
 	mutex_unlock(&file_priv->prime.lock);
 out:
 	drm_gem_object_put(obj);

 	return ret;
 }



